import{_ as t,o as a,c as o,a3 as s}from"./chunks/framework.D1GAkLkK.js";const u=JSON.parse('{"title":"Compatibility","description":"","frontmatter":{},"headers":[],"relativePath":"reference/compatibility.md","filePath":"reference/compatibility.md"}'),r={name:"reference/compatibility.md"};function i(n,e,d,l,h,c){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="compatibility" tabindex="-1">Compatibility <a class="header-anchor" href="#compatibility" aria-label="Permalink to &quot;Compatibility&quot;">​</a></h1><p>OpsTruss follows <a href="https://semver.org" target="_blank" rel="noreferrer">Semantic Versioning</a>. Within a major version, such as 1.x, a minor or patch release keeps every project, component, plugin, and script that reads <code>--json</code> working as it did, without a change on their side.</p><h2 id="what-stays" tabindex="-1">What stays <a class="header-anchor" href="#what-stays" aria-label="Permalink to &quot;What stays&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>Promised</th></tr></thead><tbody><tr><td>Files</td><td>The keys of <code>opstruss.yaml</code>, <code>opstruss.plugin.yaml</code>, <code>opstruss.catalog.yaml</code>, and <code>opstruss.lock</code>, what they mean, and their defaults; built-in tasks; the keywords and functions of expressions</td></tr><tr><td>Command line</td><td>Commands, built-in flags, exit codes, the fields of <code>--json</code> that <a href="./exit-codes-and-json">Exit codes and JSON</a> lists, and the <a href="./environment">variables</a> that it reads</td></tr><tr><td>Plugins</td><td>The <a href="./program-contract">program contract</a>: what a program gets and gives</td></tr><tr><td>State</td><td>Records, the <code>_meta</code> of each stack, <code>kv</code>, the file of each daemon, the shape of events, addresses, run ids, and the values of <code>outcome</code></td></tr><tr><td>Webhooks</td><td>The status, <code>Retry-After</code>, and JSON body of each <a href="./../guides/triggers#the-daemon">answer of the daemon</a></td></tr><tr><td>Releases</td><td>The names of the files of a release, <code>checksums.txt</code>, and what each archive holds: <code>opstruss</code> at its root, with <code>LICENSE</code>, <code>README.md</code>, and <code>CHANGELOG.md</code></td></tr></tbody></table><h2 id="what-may-change" tabindex="-1">What may change <a class="header-anchor" href="#what-may-change" aria-label="Permalink to &quot;What may change&quot;">​</a></h2><ul><li>What OpsTruss prints for people: the text at a terminal, colors, the layout of lines, and error messages. Scripts read <code>--json</code> instead.</li><li>Behavior that these pages do not describe, and fields of <code>--json</code> that they do not list.</li><li>Files that are not valid: the messages, where they point, their order, and which problem comes first. A file that a version refuses may become valid in a later one.</li><li>Bugs: where OpsTruss does not do what these pages say, a later release makes it do so.</li><li>Where files lie under <code>.opstruss/runs/</code>, <code>logs/</code>, and <code>work/</code>, and the cache in <code>~/.opstruss/</code>.</li><li>The API between the command line and the daemon, which both come from one binary.</li><li>What <code>OPSTRUSS_LOG=debug</code> prints.</li><li>What a version does not support yet, such as backend plugins and <code>mcp:</code>, which it refuses; a later version may support them.</li><li>Builds that are not releases: a release candidate, such as <code>1.0.0-rc.1</code>, a build of <code>main</code> or of any other commit, and the docs under <code>/dev/</code>.</li><li>Going back: an upgrade from any 1.x to a later 1.x keeps working; going back to an earlier one is not promised, since an older version refuses data and levels that are newer than it.</li><li>The order of the events and lines of units that run at once, how long a run takes, and the memory and disk it uses; the <a href="#limits">limits</a> only grow.</li><li>Systems outside OpsTruss: GitHub, the sources in <code>uses:</code>, and the tools that plugins run. Plugins and components have versions of their own, as <a href="./../plugins">Plugins</a> says.</li><li>Experiments: a feature that the docs call experimental runs only when you turn it on, and may change or go away in any release.</li><li>A fix of a security problem, when nothing else fixes it, also one that comes from Go or a library.</li></ul><h2 id="platforms-and-tools" tabindex="-1">Platforms and tools <a class="header-anchor" href="#platforms-and-tools" aria-label="Permalink to &quot;Platforms and tools&quot;">​</a></h2><ul><li>Releases are for Linux and macOS on amd64 and arm64. A later version may add a platform, and drops one only in a new major version. The oldest version of each operating system follows the Go release that builds OpsTruss, as the upgrade notes of the <a href="https://github.com/opstruss/opstruss/blob/main/CHANGELOG.md" target="_blank" rel="noreferrer">changelog</a> say.</li><li>The oldest <code>sops</code> that OpsTruss works with, 3.10.0, and the oldest <code>git</code> may rise in a minor release, never in a patch, as the upgrade notes say; <code>opstruss doctor</code> checks <code>sops</code>. A new feature may need a later version.</li></ul><h2 id="how-opstruss-changes" tabindex="-1">How OpsTruss changes <a class="header-anchor" href="#how-opstruss-changes" aria-label="Permalink to &quot;How OpsTruss changes&quot;">​</a></h2><ul><li><strong>It adds.</strong> A new key, field, variable, or command is optional, and without it OpsTruss behaves as before. Readers of events, plugins, and OpsTruss itself ignore fields and kinds of events they do not know. <code>outcome</code>, the <code>status</code> of a run, <code>level</code>, and <code>stream</code> keep their values, and details come in new fields; any other list of values may grow, as <a href="./exit-codes-and-json#json">Exit codes and JSON</a> says.</li><li><strong>Your names win.</strong> A built-in task, keyword, flag, or command that a later version adds gives way to a name of yours: a name in <code>uses:</code>, a task, or an input of the same name keeps working as before, and <code>validate</code> warns.</li><li><strong>It starts strict.</strong> Validation and limits start narrow and only grow looser, since what a version accepts, a later one accepts too.</li><li><strong>The level in <code>opstruss:</code>.</strong> Each file names the version of OpsTruss it is written for: <code>opstruss.yaml</code>, <code>opstruss.plugin.yaml</code>, and <code>opstruss.catalog.yaml</code>. An older OpsTruss refuses it before it reads the rest, so what a newer version added fails as the version it needs, and a newer one keeps the behavior of that level for a change that cannot be an addition. The <a href="https://github.com/opstruss/opstruss/blob/main/CHANGELOG.md" target="_blank" rel="noreferrer">changelog</a> names each such change.</li><li><strong>Deprecated is not removed.</strong> What a version deprecates keeps working until the next major version, and <code>validate</code> and each run warn about it. A later level may refuse it in a file that names that level; a file that names an older level keeps working as before, for the whole major version.</li><li><strong>Data has versions.</strong> Everything OpsTruss writes has a version, which goes up only when an older OpsTruss would read the data wrong. An older OpsTruss refuses a newer version, and says to upgrade; a newer one reads every older version and migrates it when it writes. <code>opstruss.lock</code>, which a team shares, keeps its version unless what it holds needs a newer one.</li><li><strong>Schemas stay where they are.</strong> The schema of each minor version stays at <code>https://opstruss.github.io/v&lt;major&gt;.&lt;minor&gt;/schema/</code>; a patch release never makes a file that was valid there invalid. The first line that <code>opstruss init</code> writes in <code>opstruss.yaml</code> names <code>.opstruss/schema.json</code>, which stays at that path, and which <code>init</code>, <code>validate</code>, <code>uses fetch</code>, and <code>uses update</code> write again; what it holds may change, since it only helps an editor and <code>validate</code> decides.</li><li><strong>Links stay.</strong> The page that the help of each command ends with, at <code>https://opstruss.github.io/v&lt;major&gt;.&lt;minor&gt;/reference/cli/&lt;command&gt;</code>, stays for as long as the site keeps that version; a page that moves leaves one behind that links to its new place.</li><li><strong>A break is a bug.</strong> A release that breaks what this page promises gets a patch that brings the old behavior back, unless the change fixes a security problem; a new feature that conflicts with old behavior comes through the level in <code>opstruss:</code> or a choice you make. Fixes come to the latest minor version, since an upgrade within 1.x is safe.</li></ul><p>A change that breaks what this page promises comes only in a new major version, with its upgrade in the changelog under &quot;Upgrade notes&quot;.</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><p>Each limit only grows in a later version.</p><table tabindex="0"><thead><tr><th>Limit</th><th>Value</th></tr></thead><tbody><tr><td>Outputs of a program, from a file or a stream</td><td>1 MiB</td></tr><tr><td>An input in a variable of the environment; a larger one is only in the file of <code>OPSTRUSS_INPUTS</code></td><td>64 KiB</td></tr><tr><td><code>OPSTRUSS_RESULT</code></td><td>64 KiB</td></tr><tr><td>The output of programs that a run stores; the middle of more is dropped</td><td>10 MiB</td></tr><tr><td>A value of <code>kv</code>, and keys per stack</td><td>1 MiB, 1000</td></tr><tr><td>The body of a webhook request</td><td>1 MiB</td></tr><tr><td>An event of <code>--event</code></td><td>4 MiB</td></tr><tr><td>What <code>file()</code> reads</td><td>1 MiB</td></tr><tr><td>Runs that a daemon keeps waiting or running per task</td><td>100</td></tr><tr><td>Finished runs kept per task and stack, and the size of <code>runs/</code> per stack</td><td>100, 1 GiB</td></tr></tbody></table>',14)])])}const p=t(r,[["render",i]]);export{u as __pageData,p as default};
